import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1777816303000}`),a={name:`faq.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><h2 id="新入口在哪里" tabindex="-1">新入口在哪里？ <a class="header-anchor" href="#新入口在哪里" aria-label="Permalink to “新入口在哪里？”">​</a></h2><p>官网是 <a href="https://to9.us/" target="_blank" rel="noreferrer">https://to9.us/</a>，邮箱应用是 <a href="https://to9.us/app/" target="_blank" rel="noreferrer">https://to9.us/app/</a>。旧 <code>/login</code>、<code>/admin</code>、<code>/manage</code> 和 <code>/inbox</code> 地址会自动跳转到新路径。</p><h2 id="可以用哪些方式登录" tabindex="-1">可以用哪些方式登录？ <a class="header-anchor" href="#可以用哪些方式登录" aria-label="Permalink to “可以用哪些方式登录？”">​</a></h2><p>系统支持本地账号和管理员启用的 OAuth 提供方。当前正式环境提供 NodeLoc OAuth；邮箱注册是否开放以登录页显示为准。</p><h2 id="为什么不能创建某个邮箱" tabindex="-1">为什么不能创建某个邮箱？ <a class="header-anchor" href="#为什么不能创建某个邮箱" aria-label="Permalink to “为什么不能创建某个邮箱？”">​</a></h2><p>可能原因包括地址已存在、前缀被保留、域名关闭注册、用户等级不足或套餐邮箱数量已满。邮箱管理页会显示具体原因。</p><h2 id="为什么不能发信" tabindex="-1">为什么不能发信？ <a class="header-anchor" href="#为什么不能发信" aria-label="Permalink to “为什么不能发信？”">​</a></h2><p>域名可能启用了发信审批，或账号已达到每日额度。也可能因收件人风险、抑制名单、发信通道故障或反滥用策略被阻止。先查看页面提示，再提交发信申请或工单。</p><h2 id="spf、dkim-或-dmarc-未通过是什么意思" tabindex="-1">SPF、DKIM 或 DMARC 未通过是什么意思？ <a class="header-anchor" href="#spf、dkim-或-dmarc-未通过是什么意思" aria-label="Permalink to “SPF、DKIM 或 DMARC 未通过是什么意思？”">​</a></h2><p>这些是发件域名认证结果。失败通常与发件方 DNS 或投递链路有关，不能只凭一个结果判断真假；应结合发件人身份、链接、正文和附件综合判断。</p><h2 id="第三方客户端如何登录" tabindex="-1">第三方客户端如何登录？ <a class="header-anchor" href="#第三方客户端如何登录" aria-label="Permalink to “第三方客户端如何登录？”">​</a></h2><p>使用 <code>mail.to9.us</code>，IMAPS 端口 993、POP3S 端口 995、SMTP Submission 端口 587 并启用 STARTTLS。用户名是完整邮箱地址，密码必须使用邮箱管理页生成的应用专用密码。</p><h2 id="为什么应用专用密码不能再次查看" tabindex="-1">为什么应用专用密码不能再次查看？ <a class="header-anchor" href="#为什么应用专用密码不能再次查看" aria-label="Permalink to “为什么应用专用密码不能再次查看？”">​</a></h2><p>系统只在创建时显示明文，之后只保存验证所需的信息。遗失后删除旧密码并创建新的即可。</p><h2 id="全部邮箱-会看到别人的邮件吗" tabindex="-1">“全部邮箱”会看到别人的邮件吗？ <a class="header-anchor" href="#全部邮箱-会看到别人的邮件吗" aria-label="Permalink to ““全部邮箱”会看到别人的邮件吗？”">​</a></h2><p>不会。它只汇总你拥有或已获授权访问的邮箱。</p><h2 id="删除的邮件能恢复吗" tabindex="-1">删除的邮件能恢复吗？ <a class="header-anchor" href="#删除的邮件能恢复吗" aria-label="Permalink to “删除的邮件能恢复吗？”">​</a></h2><p>普通删除可能仍在已删除区域；彻底删除、清空邮箱或已执行的清理任务通常无法从网页恢复。</p><h2 id="企业域名怎样生效" tabindex="-1">企业域名怎样生效？ <a class="header-anchor" href="#企业域名怎样生效" aria-label="Permalink to “企业域名怎样生效？”">​</a></h2><p>组织所有者添加域名后，按页面提供的 TXT 记录完成所有权验证，再配置 MX、SPF、DKIM 和 DMARC。DNS 生效后回到页面复检。</p><h2 id="订单已付款但套餐没有到账怎么办" tabindex="-1">订单已付款但套餐没有到账怎么办？ <a class="header-anchor" href="#订单已付款但套餐没有到账怎么办" aria-label="Permalink to “订单已付款但套餐没有到账怎么办？”">​</a></h2><p>先在“订单与账单”刷新状态。支付回调可能有短暂延迟；仍未到账时提交工单并提供订单号，不要提供支付密钥。</p><h2 id="管理员在哪里登录" tabindex="-1">管理员在哪里登录？ <a class="header-anchor" href="#管理员在哪里登录" aria-label="Permalink to “管理员在哪里登录？”">​</a></h2><p>通过 <a href="https://to9.us/app/login?redirect=/admin" target="_blank" rel="noreferrer">https://to9.us/app/login?redirect=/admin</a> 使用管理员账号登录。管理员密码不会以明文存储；忘记且未绑定邮箱时，需要服务器维护者重置。</p><h2 id="文档与系统不一致怎么办" tabindex="-1">文档与系统不一致怎么办？ <a class="header-anchor" href="#文档与系统不一致怎么办" aria-label="Permalink to “文档与系统不一致怎么办？”">​</a></h2><p>先查看<a href="/nodemail-docs/changelog">更新日志</a>。文档对应的功能可能受管理员开关、套餐和权限影响；确认仍不一致后提交工单。</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};